                raise RuntimeError(f"vehicle {v + 1}: cycle at station index {cur}")
            seen.add(cur)
            route.append((cur, int(round(m.getVal(h["svc"][v, cur])))))
        start_load = int(round(m.getVal(h["load"][v, START])))
